const sourceDirty = execFileSync("git", ["status", "--porcelain", "--untracked-files=normal", "--", "src"], { cwd: root, encoding: "utf8" }).trim() !== "";
const snapshot = sourceDirty ? `working tree based on ${commit}` : commit;
